import{_ as a,c as t,o as r,ah as n}from"./chunks/framework.DaDXF32t.js";const u=JSON.parse('{"title":"Shallow Git, Source Cache, and Transaction Cleanup Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-02-shallow-git-source-cache-design.md","filePath":"superpowers/specs/2026-08-02-shallow-git-source-cache-design.md","lastUpdated":1785749755000}'),o={name:"superpowers/specs/2026-08-02-shallow-git-source-cache-design.md"};function i(s,e,c,l,d,h){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="shallow-git-source-cache-and-transaction-cleanup-design" tabindex="-1">Shallow Git, Source Cache, and Transaction Cleanup Design <a class="header-anchor" href="#shallow-git-source-cache-and-transaction-cleanup-design" aria-label="Permalink to “Shallow Git, Source Cache, and Transaction Cleanup Design”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Make Git-managed installation use one shallow network transfer, retain only the current commit after a successful update, reuse measured source rankings, and prevent failed installations from accumulating staging data.</p><h2 id="git-repository-preparation" tabindex="-1">Git repository preparation <a class="header-anchor" href="#git-repository-preparation" aria-label="Permalink to “Git repository preparation”">​</a></h2><p>Main and OCR repositories remain independent and prepare concurrently. A full Git installation will use an initialized repository followed by one <code>git fetch --depth=1 --no-tags &lt;source&gt; &lt;revision&gt;</code> and a local detached checkout of <code>FETCH_HEAD</code>. It will not use a blobless partial clone, because that separates metadata transfer from the later checkout&#39;s blob transfer and displays two complete <code>Receiving objects</code> phases.</p><p>An existing Git installation will query the selected source with <code>ls-remote</code>. If the returned commit equals local <code>HEAD</code>, preparation returns unchanged and performs no fetch. Otherwise it fetches the selected revision with <code>--depth=1 --no-tags</code>, then the transaction applies the prepared commit. Both main and OCR Git repositories must report <code>true</code> from <code>git rev-parse --is-shallow-repository</code> and expose one commit from <code>git rev-list --count HEAD</code> after a successful installation.</p><p>Rollback safety temporarily requires the previous commit to remain reachable until every deployment, verification, UV, Python, and dependency step succeeds. Final Git cleanup therefore runs only after the installation transaction can no longer fail: remove installer-created temporary refs, expire reflogs, and prune unreachable objects. A failed transaction resets to the previous commit instead and does not prune rollback data prematurely.</p><h2 id="mirrorchyan-isolation" tabindex="-1">MirrorChyan isolation <a class="header-anchor" href="#mirrorchyan-isolation" aria-label="Permalink to “MirrorChyan isolation”">​</a></h2><p>MirrorChyan remains a separate repository backend and keeps its existing version query, incremental-release wait, package download, extraction, inspection, and transactional apply flow. None of the Git source selection or repository maintenance behavior is placed before or inside that flow.</p><p>Git probing, Git ranking state, shallow fetch, checkout, and post-success object pruning run only after MirrorChyan is unavailable, rejected, or not configured and the repository preparation explicitly enters its Git fallback branch. When MirrorChyan reports up to date or successfully prepares a package, the installer performs no Git probe, does not read or write that repository&#39;s Git ranking entry, and does not run Git finalization. Main and OCR decide their backend independently, so one may use MirrorChyan while the other uses Git without sharing backend-specific state.</p><p>Transaction staging cleanup is backend-neutral because the transaction owns both Git and MirrorChyan staging paths. It may remove only the transaction&#39;s verified installer-owned directory and must not change MirrorChyan package semantics or source selection.</p><h2 id="persistent-source-ranking" tabindex="-1">Persistent source ranking <a class="header-anchor" href="#persistent-source-ranking" aria-label="Permalink to “Persistent source ranking”">​</a></h2><p>Source state is stored under the protected, installation-relative directory <code>.baas-installer</code> in <code>source-ranking-v1.json</code>. It never uses a machine-global cache. Separate entries are maintained for main Git, OCR Git, UV, CPython, and PyPI. Each entry records the candidate URL, last measured latency, consecutive failure count, latest observed remote commit when applicable, and whether it was the most recent successful source.</p><p>The cache policy is cache-first and has no time-based expiry:</p><ol><li>With no matching cache, or when the configured candidate set changes, probe every candidate in that source category concurrently. Each candidate has a hard ten-second timeout, so an entire parallel measurement round is bounded to approximately ten seconds rather than ten seconds multiplied by the candidate count. Persist failed candidates as unavailable observations, exclude them from real operations during that run, save the complete ranking atomically, and try the fastest successful result first.</li><li>With a matching cache, try the most recently successful source first without probing every candidate. This cached-source operation also has a hard ten-second timeout. For Git, its required <code>ls-remote</code> freshness check updates that source&#39;s observed commit and latency.</li><li>If the cached source&#39;s real operation fails, increment its persisted failure count, concurrently probe all remaining candidates, replace the ranking, and try the refreshed successful order while excluding the already failed source.</li><li>On a successful real operation, persist the successful source as preferred and reset its consecutive failure count.</li></ol><p>Cached Git commit values are hints and diagnostics only. They never replace the live <code>ls-remote</code> comparison required to decide that a repository is current.</p><p>For Git, probing and update inspection are the same operation. Every candidate in a measurement round runs <code>git ls-remote &lt;source&gt; &lt;target-revision&gt;</code> concurrently. Its latency is measured from process start until a syntactically valid remote commit SHA is returned. A process that fails, times out after ten seconds, or returns no valid SHA is unavailable for that round. The returned SHA is reused directly for the local <code>HEAD</code> comparison and any subsequent shallow fetch; the installer must not issue a duplicate <code>ls-remote</code> after measuring that source.</p><p>All other source measurements also launch every candidate in their category concurrently with the same ten-second per-source timeout. Main and OCR preparation remain concurrent at the workflow level, so their independently scoped Git measurement rounds may overlap without sharing results.</p><h2 id="transaction-storage-lifecycle" tabindex="-1">Transaction storage lifecycle <a class="header-anchor" href="#transaction-storage-lifecycle" aria-label="Permalink to “Transaction storage lifecycle”">​</a></h2><p>Every transaction owns exactly one child directory under <code>tmp/installer</code>. Both <code>commit()</code> and <code>rollback()</code> remove that directory after their work completes. The transaction destructor performs the same rollback cleanup when control leaves unexpectedly.</p><p>At startup, the installer scans only direct children of its own installation-relative <code>tmp/installer</code> directory. It removes an abandoned child only when the resolved path remains inside that directory and the child contains the installer&#39;s <code>journal.log</code>. Other directories and files are untouched. This recovers storage left by a process crash while constraining deletion to installer-owned staging.</p><p>During a clean installation, staging and live files may coexist briefly for transactional safety. No staging copy may remain after success or handled failure.</p><h2 id="integration-with-approved-uv-and-header-changes" tabindex="-1">Integration with approved UV and header changes <a class="header-anchor" href="#integration-with-approved-uv-and-header-changes" aria-label="Permalink to “Integration with approved UV and header changes”">​</a></h2><p>Portable UV archives have no fixed digest check. A source is accepted after extraction when the installed executable succeeds with <code>uv --version</code>; failure moves to the next cached/ranked source. Dependency requirement SHA caching remains separate and continues to skip unchanged dependency resolution.</p><p>The TUI uses the approved compact six-line BAAS banner from <code>2026-08-02-uv-acceptance-and-banner-design.md</code>, with each line independently centered by terminal display width.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to “Verification”">​</a></h2><p>Automated tests must demonstrate these failures before production changes are made, then verify:</p><ul><li>a fresh Git preparation has one fetch operation, uses <code>--depth=1</code> and <code>--no-tags</code>, and does not use <code>--filter=blob:none</code>;</li><li>an unchanged repository performs <code>ls-remote</code> but no fetch;</li><li>an updated repository remains shallow with one reachable commit after successful finalization;</li><li>a successful or up-to-date MirrorChyan preparation performs no Git probe, ranking mutation, fetch, or finalization;</li><li>mixed backends keep Git state and MirrorChyan state isolated between main and OCR;</li><li>cached ranking is reused without probing every source;</li><li>a changed candidate set or failed cached source triggers a refreshed ranking;</li><li>every measurement round starts all candidates concurrently and completes within the ten-second per-source bound;</li><li>Git uses time-to-valid-remote-SHA as latency and reuses that SHA without a duplicate remote query;</li><li>source state is written atomically below <code>.baas-installer</code> and survives moving the whole installation directory;</li><li>rollback and commit remove their staging roots;</li><li>startup cleanup rejects paths without an installer journal and paths outside <code>tmp/installer</code>;</li><li>the UV and Unicode banner regression tests in the companion design pass.</li></ul><p>A disposable clean-install smoke test must confirm one <code>Receiving objects</code> phase per Git repository, one successful UV archive download, correct OCR placement, dependency completion, shallow depth-one repositories, successful BAAS launch, and no residual transaction directory after completion. The smoke directory is removed only after the applicable deletion confirmation.</p>',29)]))}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
